sys_script.script:
(function executeRule(current, previous) {

    try {
        // Delete allowed only in Draft
        if (current.getValue('status') != 'draft') {
            gs.addErrorMessage(
                'Participant Assignment can be deleted only when it is in Draft state.'
            );
            current.setAbortAction(true);
            return;
        }

        var participantAssignmentSysId = current.getUniqueValue();

        if (!participantAssignmentSysId)
            return;

        // Delete Quota Assignments first
        var quotaGR = new GlideRecordSecure('x_ctans_incentnow_user_quota_assignment');
        quotaGR.addQuery('participant_assignment', participantAssignmentSysId);
        quotaGR.query();

        while (quotaGR.next())
            quotaGR.deleteRecord();

        // Delete Plan Assignments
        var planGR = new GlideRecordSecure('x_ctans_incentnow_plan_users');
        planGR.addQuery('participant_assignment', participantAssignmentSysId);
        planGR.query();

        while (planGR.next())
            planGR.deleteRecord();

    } catch (e) {
        gs.error(
            '[IncentIQ Participant Assignment] Cascade delete failed. ' +
            'Participant Assignment=' + current.getUniqueValue() +
            ', Error=' + e.message
        );

        gs.addErrorMessage(
            'Participant Assignment could not be deleted because related assignments could not be removed.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
